{"path":"/root/solve.py","content":"#!/usr/bin/env python3
import copy
import csv
import json
from pathlib import Path

ROOT = Path('/root')


def load_json(name):
    with (ROOT / name).open('r', encoding='utf-8') as f:
        return json.load(f)


def load_csv(name):
    with (ROOT / name).open('r', encoding='utf-8', newline='') as f:
        return list(csv.DictReader(f))


def fnum(value, default=0.0):
    if value is None:
        return default
    s = str(value).strip()
    if s == '':
        return default
    return float(s)


def round2(value):
    return round(float(value) + 1e-12, 2)


def main():
    manifest = load_json('panel_manifest.json')
    holdouts = load_json('holdouts.json')
    template = load_json('report_template.json')

    shipper_rows = load_csv('shipper_cost.csv')
    contract_rows = load_csv('contract_terms.csv')
    network_rows = load_csv('network_adjustments.csv')
    override_rows = load_csv('lab_capacity_overrides.csv')

    excluded_codes = {
        row.get('panel_code')
        for row in holdouts.get('holdouts', [])
        if row.get('holdout_state') == 'exclude'
    }

    retained = []
    for cluster in manifest.get('service_clusters', []):
        for panel in cluster.get('panels', []):
            if panel.get('analysis_mode') != 'review':
                continue
            if panel.get('panel_code') in excluded_codes:
                continue
            retained.append(panel)

    network_lookup = {
        row['network_tier']: fnum(row.get('network_adjustment_per_run_per_lab_usd'))
        for row in network_rows
    }
    shipper_lookup = {
        row['shipper_class']: fnum(row.get('shipper_cost_usd'))
        for row in shipper_rows
    }

    latest_override_by_panel = {}
    for row in override_rows:
        if row.get('approval') != 'approved':
            continue
        rev_s = (row.get('rev') or '').strip()
        labs_s = (row.get('active_labs') or '').strip()
        if rev_s == '' or labs_s == '':
            continue
        try:
            rev = float(rev_s)
            active_labs = int(float(labs_s))
        except ValueError:
            continue
        panel_code = row.get('panel_code')
        current = latest_override_by_panel.get(panel_code)
        if current is None or rev > current['rev']:
            latest_override_by_panel[panel_code] = {
                'rev': rev,
                'active_labs': active_labs,
            }

    def winning_contract(panel):
        refs = {panel.get('panel_name')}
        refs.update(panel.get('alias_labels') or [])
        matches = [
            row for row in contract_rows
            if row.get('status_flag') == 'current' and row.get('panel_ref') in refs
        ]
        if not matches:
            raise ValueError(f"No current contract row matched panel {panel.get('panel_code')}")
        return max(matches, key=lambda r: r.get('effective_week') or '')

    output_panels = []
    for panel in sorted(retained, key=lambda p: p.get('panel_code', '')):
        panel_code = panel['panel_code']
        contract = winning_contract(panel)
        base_payment = fnum(contract.get('base_payment_per_run_per_lab_usd'))
        network_adjustment = network_lookup.get(panel.get('network_tier'), 0.0)
        total_payment = base_payment + network_adjustment
        active_labs = latest_override_by_panel.get(panel_code, {}).get(
            'active_labs', int(panel.get('default_active_labs'))
        )
        shipper_cost_per_shipment = shipper_lookup[panel['shipper_class']]
        reagent_per_1000 = fnum(panel.get('reagent_cost_per_1000_tests_usd'))

        calc = {}
        for label, runs, tests_key in (
            ('14_day', 26, 'tests_per_lab_per_run_14_day'),
            ('28_day', 13, 'tests_per_lab_per_run_28_day'),
        ):
            tests_per_lab_per_run = fnum(panel.get(tests_key))
            annual_revenue = total_payment * active_labs * runs
            annual_reagent_cost = reagent_per_1000 * active_labs * tests_per_lab_per_run * runs / 1000.0
            # Test-contract interpretation: shipper cost is per shipment per active lab per run.
            annual_shipper_cost = shipper_cost_per_shipment * active_labs * runs
            annual_margin = annual_revenue - annual_reagent_cost - annual_shipper_cost
            calc[label] = {
                'runs_per_year': runs,
                'tests_per_lab_per_run': int(tests_per_lab_per_run) if tests_per_lab_per_run.is_integer() else tests_per_lab_per_run,
                f'annual_revenue_{label}_usd': round2(annual_revenue),
                f'annual_reagent_cost_{label}_usd': round2(annual_reagent_cost),
                f'annual_shipper_cost_{label}_usd': round2(annual_shipper_cost),
                f'annual_margin_{label}_usd': round2(annual_margin),
            }

        margin_14 = calc['14_day']['annual_margin_14_day_usd']
        margin_28 = calc['28_day']['annual_margin_28_day_usd']
        output_panels.append({
            'panel_code': panel_code,
            'panel_name': panel['panel_name'],
            'active_labs': active_labs,
            'contract_panel_ref': contract['panel_ref'],
            'contract_effective_week': contract['effective_week'],
            'base_payment_per_run_per_lab_usd': round2(base_payment),
            'network_tier': panel.get('network_tier'),
            'network_adjustment_per_run_per_lab_usd': round2(network_adjustment),
            'total_payment_per_run_per_lab_usd': round2(total_payment),
            'shipper_class': panel.get('shipper_class'),
            'shipper_cost_usd': round2(shipper_cost_per_shipment),
            'reagent_cost_per_1000_tests_usd': round2(reagent_per_1000),
            **calc['14_day'],
            **calc['28_day'],
            'annual_margin_difference_28_minus_14_usd': round2(margin_28 - margin_14),
        })

    total_14 = round2(sum(p['annual_margin_14_day_usd'] for p in output_panels))
    total_28 = round2(sum(p['annual_margin_28_day_usd'] for p in output_panels))
    total_diff = round2(total_28 - total_14)
    abs_diff = round2(abs(total_diff))
    decision_slug = 'adopt_28_day' if abs_diff < 6000 else 'keep_14_day'

    report = copy.deepcopy(template)
    report['analysis'] = {
        'assumptions': {
            'retained_panel_rule': 'analysis_mode == review and holdout_state != exclude',
            'contract_match_rule': 'panel_name or alias_labels, current status, latest effective_week',
            'cadence_runs_per_year': {'14_day': 26, '28_day': 13},
            'annual_shipper_cost_formula': 'shipper_cost_usd * active_labs * runs_per_year',
            'currency_rounding': 'round to 2 decimal places',
        },
        'panels': output_panels,
        'totals': {
            'total_annual_margin_14_day_usd': total_14,
            'total_annual_margin_28_day_usd': total_28,
            'total_annual_margin_difference_28_minus_14_usd': total_diff,
            'absolute_total_margin_difference_usd': abs_diff,
        },
        'recommendation': {
            'decision_slug': decision_slug,
            'rationale': 'Adopt 28-day cadence when the absolute annual margin difference is below $6,000; otherwise keep 14-day cadence.',
        },
    }

    with (ROOT / 'diagpanel_policy_report.json').open('w', encoding='utf-8') as f:
        json.dump(report, f, indent=2)
        f.write('\n')

    summary_lines = [
        '# Diagnostic Panel Cadence Policy Summary',
        f'Total annual margin at 14-day cadence: ${total_14:,.2f}',
        f'Total annual margin at 28-day cadence: ${total_28:,.2f}',
        f'Absolute total margin difference: ${abs_diff:,.2f}',
        f'Decision slug: {decision_slug}',
        f'Panels analyzed: {len(output_panels)}',
    ]
    with (ROOT / 'diagpanel_policy_summary.md').open('w', encoding='utf-8') as f:
        f.write('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()
